    verify(mockQueryRunner).insert("1", handler);
    verify(mockQueryRunner).insert("2", handler, "param1");
    verify(mockQueryRunner).insert(conn, "3", handler);
    verify(mockQueryRunner).insert(conn, "4", handler, "param1");
}

